mapper.update:
UPDATE CLOVER_USER
   SET user_nm       = #{userNm}
     , user_state    = #{userState}
     , pswd_init_yn  = #{pswdInitYn}
     , bryy_mndy     = #{bryyMndy}
     , user_tno      = #{userTno}
     , user_exno     = #{userExno}
     , user_gd       = #{userGd}
     , cti_user_ntno = #{ctiUserNtno}
     , prt_posb_yn   = #{prtPosbYn}
     , dwnl_posb_yn  = #{dwnlPosbYn}
     , atnt_yn       = #{atntYn}
     , memo          = #{memo}
     , team_id       = #{teamId}
     , chgr_id       = #{chgrId}
     , chng_dttm     = CURRENT_TIMESTAMP
 WHERE user_id = #{userId}

UPDATE CLOVER_USER
   SET last_lgon_dttm = CURRENT_TIMESTAMP
     , chgr_id        = #{chgrId}
     , chng_dttm      = CURRENT_TIMESTAMP
 WHERE user_id = #{userId}

