mapper.update:
UPDATE CLOVER_USER
   SET pswd_init_yn = 'Y'
     , pswd         = #{pswd}
     , chgr_id      = #{chgrId}
     , chng_dttm    = CURRENT_TIMESTAMP
 WHERE user_id = #{userId}

UPDATE CLOVER_USER
   SET pswd_init_yn        = 'N'
     , pswd                = #{pswd}
     , chng_dttm           = CURRENT_TIMESTAMP
     , last_pswd_chng_dttm = CURRENT_TIMESTAMP
 WHERE user_id = #{userId}

UPDATE CLOVER_USER
   SET lgon_fail_cnt = lgon_fail_cnt + 1
     , chgr_id       = #{chgrId}
     , chng_dttm     = CURRENT_TIMESTAMP
 WHERE user_id = #{userId}


UPDATE CLOVER_USER
   SET PSWD_INIT_YN = 'Y'
 WHERE reg_dttm <= #{value}
